<script setup lang="ts">
import {onMounted,ref} from 'vue'; import {ElMessage} from 'element-plus'; import {api} from '../api';
type Ledger={type:string;amount:number;balanceAfter:number;referenceType:string;idempotencyKey:string;createdAt:string;user:{nickname:string|null;wechatId:string}};const records=ref<Ledger[]>([]),keyword=ref(''),type=ref(''),total=ref(0),loading=ref(false),labels:Record<string,string>={EARN:'获得',SPEND:'消费',REVERSAL:'冲正'};
async function load(page=1){loading.value=true;try{const {data}=await api.get('/admin/point-ledgers',{params:{page,pageSize:20,keyword:keyword.value,type:type.value||undefined}});records.value=data.items;total.value=data.total;}catch(error:any){ElMessage.error(error.response?.data?.message||'读取积分流水失败');}finally{loading.value=false;}}onMounted(load);
</script>
<template><section><h1>任务与积分</h1><el-alert title="积分流水为追加式账本：已入账记录不可编辑，只能生成冲正记录。" type="warning" :closable="false" class="notice"/><el-card><div class="toolbar"><el-input v-model="keyword" placeholder="搜索用户、来源或幂等键" @keyup.enter="load()"/><el-select v-model="type" clearable placeholder="全部类型" style="width:130px"><el-option label="获得" value="EARN"/><el-option label="消费" value="SPEND"/><el-option label="冲正" value="REVERSAL"/></el-select><el-button type="primary" @click="load()">查询</el-button></div><el-table :data="records" v-loading="loading"><el-table-column label="时间"><template #default="{row}">{{new Date(row.createdAt).toLocaleString()}}</template></el-table-column><el-table-column label="用户"><template #default="{row}">{{row.user.nickname||row.user.wechatId}}</template></el-table-column><el-table-column label="类型"><template #default="{row}"><el-tag>{{labels[row.type]}}</el-tag></template></el-table-column><el-table-column prop="amount" label="变动"/><el-table-column prop="balanceAfter" label="变动后余额"/><el-table-column prop="referenceType" label="业务来源"/><el-table-column prop="idempotencyKey" label="幂等键"/></el-table><el-pagination v-if="total" layout="total, prev, pager, next" :total="total" class="pagination" @current-change="load"/></el-card></section></template>
